{
  "name": "rf_path_switch_configure",
  "confidence": "medium",
  "docstring": "Updates the RF path switch for a wireless context by clearing its TX-power entry, selecting an active low-band peer interface from the context list, programming the RF register, and issuing coexistence/HCI completion messages.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "vif_ctx",
    "v5": "iter_ctx",
    "v6": "other_ctx_freq",
    "v12": "active_flag_msg",
    "v7": "coex_msg"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "intrusive next-pointer used while walking the active context list"
    },
    {
      "offset": 107,
      "meaning": "interface/path/channel identifier (u8), used to index TX-power state and switch messages"
    },
    {
      "offset": 108,
      "meaning": "context active/connected flag (u8)"
    },
    {
      "offset": 416,
      "meaning": "frequency/channel value (u16), compared against 0x1387 for low-band selection"
    },
    {
      "offset": 413,
      "meaning": "RF path/register selector byte (u8) placed into the switch register value"
    },
    {
      "offset": 72,
      "meaning": "coexistence/feature enable or context descriptor (u32) that triggers an additional HCI/coex message"
    }
  ]
}
